-- 1073: Move inline Learning Outcomes out of the course description and into
-- the per-course `course_<sku>_learning_outcomes` cms/block for the 4 courses
-- that still carried them inline (sitewide audit 2026-08-21). Same shape as
-- migration 1033 (TGS-2020505550): these headings are INVISIBLE to
-- view.phtml::$_extractSection -- three use "<h2>Course Learning Outcomes</h2>"
-- (leading "Course " defeats the 'Learning\s+Outcomes' anchor) and one uses a
-- <p><span font-size:1.5em> pseudo-heading (not an <h[1-6]> at all) -- so the
-- LOs rendered inside "What's This Course About" and the card stayed empty.
-- BOTH halves are required per course: seed the block AND strip the section.
--
-- TGS-2026064180 additionally drops its "<h2>Course Objective</h2>" one-liner
-- (explicit request; not moved anywhere).
--
-- Data-only (view.phtml already reads block-first). Block content is the
-- section BODY only, no heading -- the card supplies its own. Byte-exact
-- literals generated from PROD bytes (local DB is a stale restore). Idempotent:
-- guarded INSERTs; REPLACE strips no-op once applied or on any partner row
-- whose bytes diverge.

-- ============ TGS-2026064180 ============
SET @sku := 'TGS-2026064180';
SET @e := (SELECT entity_id FROM catalog_product_entity WHERE sku = @sku LIMIT 1);
SET @a_sd := (SELECT attribute_id FROM eav_attribute
              WHERE entity_type_id = 4 AND attribute_code = 'short_description' LIMIT 1);
SET @ident := CONCAT('course_', @sku, '_learning_outcomes');
SET @lo_body := UNHEX('');

INSERT INTO cms_block (title, identifier, content, creation_time, update_time, is_active)
SELECT CONCAT('Course ', @sku, ' Learning Outcomes'), @ident, @lo_body, NOW(), NOW(), 1
FROM dual
WHERE @e IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM (SELECT * FROM cms_block) b WHERE b.identifier = @ident);

INSERT IGNORE INTO cms_block_store (block_id, store_id)
SELECT b.block_id, 0 FROM cms_block b WHERE b.identifier = @ident;

SET @strip_course_objective := UNHEX('3C68323E436F75727365204F626A6563746976653C2F68323E3C703E4C6561726E6572732077696C6C2062652061626C6520746F20706572666F726D20737461746973746963616C20616E616C79736973207769746820616E616C797469637320746F6F6C733C2F703E');
UPDATE catalog_product_entity_text v
SET v.value = REPLACE(v.value, @strip_course_objective, '')
WHERE v.entity_id = @e
  AND v.attribute_id = @a_sd
  AND @e IS NOT NULL
  AND LOCATE(@strip_course_objective, v.value) > 0;

SET @strip_learning_outcomes := UNHEX('');
UPDATE catalog_product_entity_text v
SET v.value = REPLACE(v.value, @strip_learning_outcomes, '')
WHERE v.entity_id = @e
  AND v.attribute_id = @a_sd
  AND @e IS NOT NULL
  AND LOCATE(@strip_learning_outcomes, v.value) > 0;

